CREATE TABLE `lh_login_throttle` (`id` bigint(20) NOT NULL AUTO_INCREMENT,`type` int(11) NOT NULL,`identifier` varchar(190) NOT NULL,`attempts` int(11) NOT NULL DEFAULT 0,`first_attempt` bigint(20) NOT NULL DEFAULT 0,`last_attempt` bigint(20) NOT NULL DEFAULT 0,`locked_until` bigint(20) NOT NULL DEFAULT 0,`lock_count` int(11) NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `type_identifier` (`type`,`identifier`),KEY `locked_until` (`locked_until`),KEY `last_attempt` (`last_attempt`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
